'use strict';

// MODULES //

var tape = require( 'tape' );
var ndarraylike2descriptor = require( '@stdlib/ndarray/base/ndarraylike2descriptor' );
var slice = require( '@stdlib/ndarray/slice' );
var zeros = require( '@stdlib/ndarray/zeros' );
var offsets = require( '@stdlib/ndarray/base/offsets' );
var MultiSlice = require( '@stdlib/slice/multi' );
var setDescriptorOffsets = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof setDescriptorOffsets, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function sets index offsets', function test( t ) {
	var expected;
	var actual;
	var desc;
	var out;
	var v;
	var x;

	x = zeros( [ 3, 3, 3 ] );
	v = slice( x, new MultiSlice( 0, null, null ) );

	desc = [
		ndarraylike2descriptor( v ),
		ndarraylike2descriptor( v ),
		ndarraylike2descriptor( v )
	];

	out = setDescriptorOffsets( desc, [ 0, 9, 18 ] );
	t.strictEqual( out, desc, 'returns expected value' );

	actual = offsets( out );
	expected = [ 0, 9, 18 ];
	t.deepEqual( actual, expected, 'returns expected value' );

	t.end();
});
